-- ==============================================================================
-- HyperXOS Windows 11 Fluent Theme for Hyprland (Lua Configuration)
-- ==============================================================================

-- Explicitly disable the autogenerated warning banner and wizard
hl.config({
    autogenerated = false,
})

-- Monitor Configuration (Automatic display detection)
hl.config({
    monitor = {
        { name = "", preferred = true, auto = true, scale = 1.0 },
    },
})

-- Input Configuration (Windows-style standard behavior)
hl.config({
    input = {
        kb_layout = "us",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
            tap_to_click = true,
            drag_lock = true,
        },
    },
})

-- General Layout & Windows 11 Fluent Accent Borders
hl.config({
    general = {
        gaps_in = 6,
        gaps_out = 10,
        border_size = 1,
        ["col.active_border"] = "rgba(0078d4ff) rgba(8b5cf6ff) 45deg",
        ["col.inactive_border"] = "rgba(1e293b99)",
        layout = "dwindle",
        resize_on_border = true,
        hover_icon_on_border = true,
    },
})

-- Visual Decorations (Dual-Kawase Blur & Acrylic Glassmorphism)
hl.config({
    decoration = {
        rounding = 10,
        active_opacity = 0.98,
        inactive_opacity = 0.92,
        blur = {
            enabled = true,
            size = 6,
            passes = 3,
            new_optimizations = true,
            vibrancy = 0.20,
            ignore_opacity = true,
        },
        shadow = {
            enabled = true,
            range = 18,
            render_power = 3,
            color = "rgba(0, 0, 0, 0.40)",
        },
    },
})

-- Windows 11 Fluent Smooth Animations
hl.config({
    animations = {
        enabled = true,
        bezier = {
            fluentDecel = { 0.05, 0.9, 0.1, 1.0 },
            fluentEase = { 0.16, 1, 0.3, 1 },
        },
        animation = {
            { name = "windows", enabled = true, speed = 4, curve = "fluentDecel", style = "popin 80%" },
            { name = "windowsOut", enabled = true, speed = 3, curve = "fluentEase", style = "popin 80%" },
            { name = "border", enabled = true, speed = 6, curve = "default" },
            { name = "fade", enabled = true, speed = 4, curve = "fluentEase" },
            { name = "workspaces", enabled = true, speed = 4, curve = "fluentDecel", style = "slide" },
        },
    },
})

-- Dwindle Layout
hl.config({
    dwindle = {
        pseudotile = true,
        preserve_split = true,
    },
})

-- Misc Display Tweaks
hl.config({
    misc = {
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
        force_default_wallpaper = 0,
        vfr = true,
    },
})

-- Autostart Applications & Daemons on Hyprland startup
hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user start hyprpolkitagent || /usr/lib/hyprpolkitagent &")
    hl.exec_cmd("hyprpaper &")
    hl.exec_cmd("waybar &")
    hl.exec_cmd("swaync &")
    hl.exec_cmd("wl-paste --type text --watch cliphist store &")
    hl.exec_cmd("wl-paste --type image --watch cliphist store &")
end)

-- Window Rules for Floating Utilities & Dialogs
hl.window_rule({ match = { class = "wofi" }, float = true })
hl.window_rule({ match = { class = "pavucontrol" }, float = true })
hl.window_rule({ match = { class = "nm-connection-editor" }, float = true })
hl.window_rule({ match = { class = "hyper-x-tools" }, float = true, size = { 1024, 640 }, center = true })
hl.window_rule({ match = { class = "hyper-x-installer" }, float = true, size = { 1120, 720 }, center = true })
hl.window_rule({ match = { class = "thunar", title = "File Operation Progress" }, float = true })
hl.window_rule({ match = { class = "thunar", title = "Confirm to replace files" }, float = true })
hl.window_rule({ match = { title = "Open File" }, float = true })
hl.window_rule({ match = { title = "Save File" }, float = true })

-- ==============================================================================
-- Windows 11 Keyboard Shortcuts & Navigation
-- ==============================================================================

-- Start Menu (Tap Super / Windows key)
hl.bind("SUPER_L", hl.dsp.exec_cmd("pkill wofi || wofi --show drun"), { release = true })
hl.bind("SUPER", hl.dsp.exec_cmd("pkill wofi || wofi --show drun"))

-- File Explorer (Win + E)
hl.bind("SUPER + E", hl.dsp.exec_cmd("thunar"))

-- Action Center & Quick Settings (Win + A)
hl.bind("SUPER + A", hl.dsp.exec_cmd("swaync-client -t -sw"))

-- Clipboard History (Win + V)
hl.bind("SUPER + V", hl.dsp.exec_cmd("cliphist list | wofi -dmenu -p 'Clipboard' | cliphist decode | wl-copy"))

-- Snipping Tool / Screenshot (Win + Shift + S)
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | swappy -f -"))

-- Lock Screen (Win + L)
hl.bind("SUPER + L", hl.dsp.exec_cmd("hyprlock"))

-- Core Applications
hl.bind("SUPER + Return", hl.dsp.exec_cmd("foot"))
hl.bind("SUPER + T", hl.dsp.exec_cmd("foot"))
hl.bind("SUPER + B", hl.dsp.exec_cmd("firefox"))

-- Window Controls ala Windows
hl.bind("ALT + F4", hl.dsp.window.kill())
hl.bind("SUPER + Q", hl.dsp.window.kill())
hl.bind("SUPER + Up", hl.dsp.window.fullscreen({ mode = 1 }))
hl.bind("SUPER + Down", function()
    hl.dispatch(hl.dsp.window.float())
end)
hl.bind("SUPER + Left", hl.dsp.window.move({ direction = "l" }))
hl.bind("SUPER + Right", hl.dsp.window.move({ direction = "r" }))
hl.bind("SUPER + D", hl.dsp.workspace.toggle_special({ name = "desktop" }))
hl.bind("ALT + Tab", function()
    hl.dispatch(hl.dsp.window.cycle_next())
    hl.dispatch(hl.dsp.window.alter_zorder({ mode = "top" }))
end)

-- Mouse Window Control (Super + Drag / Resize)
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Volume & Media Keys
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"), { repeating = true, locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { repeating = true, locked = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set 5%+"), { repeating = true, locked = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"), { repeating = true, locked = true })
